{"rootElement":[{"artifact":[{"extensionElements":{"nodeVisualInfo":[{"width":279,"x":74,"y":142,"declaredType":"TNodeVisualInfo","height":42}]},"declaredType":"textAnnotation","text":{"content":["This service is sending notification email to initiator(Hub or branch) and cad team "]},"id":"10be519d-cf58-42b7-813e-c2ddf923330e","textFormat":"text/plain"}],"flowElement":[{"parallelMultiple":false,"outgoing":["2027.31cc3afd-bf1d-4b1e-a33a-d74566368d54"],"isInterrupting":false,"extensionElements":{"nodeVisualInfo":[{"color":"#F8F8F8","width":24,"x":25,"y":40,"declaredType":"TNodeVisualInfo","height":24}]},"name":"Start","declaredType":"startEvent","id":"71e1f5fd-4743-4920-b7ab-80c47f5448a0"},{"incoming":["09e58633-fedc-482e-a9b3-f53a3e9be7fa","b714823a-5fc2-496c-83db-5f9679051e0a"],"extensionElements":{"nodeVisualInfo":[{"color":"#F8F8F8","width":24,"x":650,"y":40,"declaredType":"TNodeVisualInfo","height":24}],"endStateId":["guid:4e45c66327642938:4e8a44d0:18bf1ac4de4:-5cb3"],"saveExecutionContext":[true]},"name":"End","declaredType":"endEvent","id":"92a603e5-f642-4a9a-920d-97380ea73695"},{"targetRef":"3c60b45c-205a-41bf-baf3-3d5e5be0c1c9","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Init Data","declaredType":"sequenceFlow","id":"2027.31cc3afd-bf1d-4b1e-a33a-d74566368d54","sourceRef":"71e1f5fd-4743-4920-b7ab-80c47f5448a0"},{"startQuantity":1,"outgoing":["b7e9eed0-3a64-47e5-9726-0acea484f5e1"],"incoming":["2027.31cc3afd-bf1d-4b1e-a33a-d74566368d54"],"extensionElements":{"nodeVisualInfo":[{"width":95,"x":106,"y":17,"declaredType":"TNodeVisualInfo","height":70}]},"name":"Init Data","isForCompensation":false,"completionQuantity":1,"declaredType":"scriptTask","id":"3c60b45c-205a-41bf-baf3-3d5e5be0c1c9","scriptFormat":"text/x-javascript","script":{"content":["//set variables
tw.local.instanceNum = String(tw.local.odcRequest.instanceNo);
tw.local.CIF = String(tw.local.odcRequest.cif);
tw.local.currency = String(tw.local.odcRequest.FinancialDetailsBR.currency.name);
tw.local.docAmnt  = String(tw.local.odcRequest.FinancialDetailsBR.documentAmount); 
tw.local.collectableAmnt= String(tw.local.odcRequest.FinancialDetailsFO.collectableAmount);

//Set Mail Subject
tw.local.subject = "Remittance letter for ODC Request No. "+tw.local.odcRequest.appInfo.instanceID
			+" for Customer "+tw.local.odcRequest.CustomerInfo.customerName
			+" is ready.";

//Set Cad Mail
tw.local.mailToCAD= tw.epv.Mails.Cad;

//Set Intiator Mail			
	//Branch Intiator
	if(tw.local.routingDetails.branchCode != null && tw.local.routingDetails.branchCode != "" ){
		var branch_Makers= String(tw.epv.Mails.BR_Maker);
		tw.local.mailToInitiator = branch_Makers.replace("xxx",tw.local.routingDetails.branchCode);		
	}
	//Hub Intiator
	else{
		var hub_Makers= String(tw.epv.Mails.Hub_Maker);
		tw.local.mailToInitiator = hub_Makers.replace("xxx",tw.local.routingDetails.hubCode);		
	}
	"]}},{"startQuantity":1,"outgoing":["0f739008-93a7-4427-88ae-ed487a957da3"],"incoming":["4420f95c-9d87-41e3-a1ce-4fda80ab2daa"],"extensionElements":{"nodeVisualInfo":[{"width":95,"x":341,"y":17,"declaredType":"TNodeVisualInfo","height":70}],"activityType":["CalledProcess"]},"name":"Send Mail To Initiator","dataInputAssociation":[{"targetRef":"2055.ae81d59d-2fde-4526-9476-d0598d6e8472","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.subject"]}}]},{"targetRef":"2055.6d9bd911-88b8-4ea3-8823-421a4f690290","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.msgBody"]}}]},{"targetRef":"2055.1da05789-2131-46bc-aacf-34d84ca37def","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.mailDebugMode"]}}]},{"targetRef":"2055.20348cf5-023e-4d3a-826e-5b92143ec224","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":[""""]}}]},{"targetRef":"2055.268afc2e-a651-49ef-8704-9a6ff22065c6","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.c09c9b6e-aabd-4897-bef2-ed61db106297","declaredType":"TFormalExpression","content":["null"]}}]},{"targetRef":"2055.a7c74b41-811f-4581-94ef-69a84c74eb84","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.mailToInitiator"]}}]}],"isForCompensation":false,"completionQuantity":1,"declaredType":"callActivity","id":"3c4c17fc-3239-4048-a6c9-ffafb1814137","dataOutputAssociation":[{"assignment":[{"to":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.errorMsg"]}}],"sourceRef":["2055.ec26c46c-d70b-4881-98d8-40e694dd7362"]}],"calledEle