  '<!DOCTYPE html>' +
  '<html lang="en" dir="ltr">' +
  '<head>' +
    '<meta charset="UTF-8">' +
    '<style>' +
      'body { font-family: Arial, sans-serif; margin: 30px; color: #333; line-height: 1.6; }' +
      '.container { max-width: 700px; margin: 0 auto; }' +
      'h2 { color: #005baa; }' +
      '.details { background-color: #f7f7f7; padding: 15px; border: 1px solid #ccc; margin-top: 10px; }' +
      '.details p { margin: 6px 0; }' +
      '.note { margin-top: 30px; font-size: 0.95em; color: #aa0000; font-style: italic; }' +
      '.footer { margin-top: 40px; font-size: 0.9em; color: #666; }' +
    '</style>' +
  '</head>' +
  '<body>' +
    '<div class="container">' +
      '<h2>Remittance Letter Ready for Printing</h2>' +

      '<p>Dear Sir / Madam,</p>' +

      '<p>' +
        'Please be informed that the <strong>Remittance Letter</strong> for ' +
        '<strong>' + tw.local.odcRequest.BasicDetails.requestType + '</strong> ' +
        '(Request No. <strong>' + tw.local.odcRequest.appInfo.instanceID + '</strong>) ' +
        'related to the customer <strong>' + tw.local.odcRequest.CustomerInfo.customerName + '</strong> ' +
        'is now ready for printing.' +
      '</p>' +

      '<p>You can find the document under the <strong>"Print Remittance Letter"</strong> activity in your BPM inbox.</p>' +

      '<div class="details">' +
        '<p><strong>Instance Number:</strong> ' + tw.local.instanceNum + '</p>' +
        '<p><strong>CIF No.:</strong> ' + tw.local.CIF + '</p>' +
        '<p><strong>Currency:</strong> ' + tw.local.currency + '</p>' +
        '<p><strong>Document Amount:</strong> ' + tw.local.docAmnt + '</p>' +
        '<p><strong>Collectable Amount:</strong> ' + tw.local.collectableAmnt + '</p>' +
      '</div>' +

      '<p class="note">Please do not reply to this message. This is an automatically generated email.</p>' +

      '<div class="footer">' +
        'Kind regards,<br>' +
        '<em>Automated Notification System</em>' +
      '</div>' +
    '</div>' +
  '</body>' +
  '</html>';"]}},{"targetRef":"3c4c17fc-3239-4048-a6c9-ffafb1814137","extensionElements":{"linkVisualInfo":[{"sourcePortLocation":"rightCenter","showCoachControlLabel":false,"labelPosition":0.0,"targetPortLocation":"leftCenter","declaredType":"TLinkVisualInfo","saveExecutionContext":false,"showLabel":false}]},"name":"To Service","declaredType":"sequenceFlow","id":"4420f95c-9d87-41e3-a1ce-4fda80ab2daa","sourceRef":"aabe0874-8452-4041-b267-51bf928d5bfb"},{"startQuantity":1,"outgoing":["09e58633-fedc-482e-a9b3-f53a3e9be7fa"],"incoming":["024362c6-3960-4108-9a5b-5eb4d23f806b"],"extensionElements":{"nodeVisualInfo":[{"color":"#FF7782","width":95,"x":483,"y":108,"declaredType":"TNodeVisualInfo","height":70}],"activityType":["CalledProcess"]},"name":"Exp. Handling","dataInputAssociation":[{"targetRef":"2055.5ea77901-7a17-422a-8958-67bb0e9c991b","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":[""Send Mail to CAD Team""]}}]},{"targetRef":"2055.55dcd590-97c2-48df-82c6-0f812ab7177f","assignment":[{"from":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":[""""]}}]}],"isForCompensation":false,"completionQuantity":1,"declaredType":"callActivity","id":"ee0a03f4-9375-4de7-b824-749b5c750505","dataOutputAssociation":[{"assignment":[{"to":{"evaluatesToTypeRef":"itm.12.db884a3c-c533-44b7-bb2d-47bec8ad4022","declaredType":"TFormalExpression","content":["tw.local.errorMsg"]}}],"sourceRef":["2055.81b82125-a5aa-45f7-8c0f-4870667eebbf"]}],"calledElement":"1.2b50ff68-f7d3-4895-88ad-a73a13fa91d0"},{"parallelMultiple":false,"outgoing":["024362c6-3960-4108-9a5b-5eb4d23f806b"],"eventDefinition":[{"extensionElements":{"errorEventSettings":[{"catchAll":true,"declaredType":"com.ibm.bpmsdk.model.bpmn20.ibmwleext.TErrorEventSettings"}]},"declaredType":"errorEventDefinition","id":"167eef3c-374c-468b-a0bb-d14172fd99c4","otherAttributes":{"eventImplId":"81