ns16:scriptTask.ns16:script:
//set variables
tw.local.instanceNum = String(tw.local.odcRequest.instanceNo);
tw.local.CIF = String(tw.local.odcRequest.cif);
tw.local.currency = String(tw.local.odcRequest.FinancialDetailsBR.currency.name);
tw.local.docAmnt  = String(tw.local.odcRequest.FinancialDetailsBR.documentAmount); 
tw.local.collectableAmnt= String(tw.local.odcRequest.FinancialDetailsFO.collectableAmount);

//Set Mail Subject
tw.local.subject = "Remittance letter for ODC Request No. "+tw.local.odcRequest.appInfo.instanceID
			+" for Customer "+tw.local.odcRequest.CustomerInfo.customerName
			+" is ready.";

//Set Cad Mail
tw.local.mailToCAD= tw.epv.Mails.Cad;

//Set Intiator Mail			
	//Branch Intiator
	if(tw.local.routingDetails.branchCode != null && tw.local.routingDetails.branchCode != "" ){
		var branch_Makers= String(tw.epv.Mails.BR_Maker);
		tw.local.mailToInitiator = branch_Makers.replace("xxx",tw.local.routingDetails.branchCode);		
	}
	//Hub Intiator
	else{
		var hub_Makers= String(tw.epv.Mails.Hub_Maker);
		tw.local.mailToInitiator = hub_Makers.replace("xxx",tw.local.routingDetails.hubCode);		
	}
